CREATE TABLE IF NOT EXISTS subcontract_boq_sections(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,subcontract_boq_id BIGINT UNSIGNED NOT NULL,work_section_id BIGINT UNSIGNED NULL,section_code VARCHAR(30) NOT NULL,title VARCHAR(190) NOT NULL,description TEXT NULL,sort_order INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_subcontract_boq_sections_order(subcontract_boq_id,sort_order),CONSTRAINT fk_subcontract_boq_sections_boq FOREIGN KEY(subcontract_boq_id) REFERENCES subcontract_boqs(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_boq_sections_master FOREIGN KEY(work_section_id) REFERENCES work_sections(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontract_boq_sections_sort CHECK(sort_order>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
